                                "size": "lg",
                                "color": "#FFFFFF",
                                "weight": "bold",
                                "margin": "md"
                            },
                            {
                                "type": "text",
                                "text": "雷雨の可能性が高い",
                                "size": "sm",
                                "color": "#FFFFFFEE",
                                "wrap": true
                            }
                        ]
                    },
                    {
                        "type": "box",
                        "layout": "vertical",
                        "flex": 4,
                        "gravity": "center",
                        "contents": [
                            {
                                "type": "image",
                                "url": "https://cdn-icons-png.flaticon.com/512/1146/1146860.png",
                                "size": "full",
                                "aspectMode": "fit",
                                "align": "end"
                            }
                        ]
                    }
                ]
            },
            {
                "type": "box",
                "layout": "vertical",
                "margin": "xl",
                "paddingAll": "10px",
                "contents": [
                    {
                        "type": "box",
                        "layout": "horizontal",
                        "contents": [
                            {
                                "type": "box",
                                "layout": "vertical",
                                "contents": [
                                    {
                                        "type": "text",
                                        "text": "相對濕度",
                                        "size": "xxs",
                                        "color": "#AAAAAA"
                                    },
                                    {
                                        "type": "text",
                                        "text": "88%",
                                        "weight": "bold",
                                        "size": "sm",
                                        "color": "#333333"
                                    }
                                ]
                            },
                            {
                                "type": "separator"
                            },
                            {
                                "type": "box",
                                "layout": "vertical",
                                "contents": [
                                    {
                                        "type": "text",
                                        "text": "雨の予想",
                                        "size": "xxs",
                                        "color": "#AAAAAA"
                                    },
                                    {
                                        "type": "text",
                                        "text": "14:00 頃",
                                        "weight": "bold",
                                        "size": "sm",
                                        "color": "#333333"
                                    }
                                ],
                                "paddingLeft": "xl"
                            }
                        ],
                        "spacing": "xl"
                    }
                ]
            },
            {
                "type": "box",
                "layout": "vertical",
                "margin": "md",
                "backgroundColor": "#F8F9FA",
                "cornerRadius": "lg",
                "paddingAll": "15px",
                "contents": [
                    {
                        "type": "text",
                        "text": "午後は激しい雨に注意。室内での活動をおすすめします ⛈️",
                        "size": "xs",
                        "color": "#555555",
                        "wrap": true
                    }
                ]
            }
        ]
    },
    "footer": {
        "type": "box",
        "layout": "vertical",
        "paddingBottom": "15px",
        "paddingStart": "15px",
        "paddingEnd": "15px",
